refentry.refsect1:
  &reftitle.examples;



    Esempi di array_splice


<?php
$input = array("rosso", "verde", "blu", "giallo");
array_splice($input, 2);
var_dump($input);

$input = array("rosso", "verde", "blu", "giallo");
array_splice($input, 1, -1);
var_dump($input);

$input = array("rosso", "verde", "blu", "giallo");
array_splice($input, 1, count($input), "arancione");
var_dump($input);

$input = array("rosso", "verde", "blu", "giallo");
array_splice($input, -1, 1, array("nero", "bordeaux"));
var_dump($input);
?>


