    Istruzioni equivalenti a vari esempi di array_splice


     Le seguenti istruzioni sono equivalenti:



<?php

// aggiunge due elementi a $input
array_push($input, $x, $y);
array_splice($input, count($input), 0, array($x, $y));

// rimuove l'ultimo elemento di $input
array_pop($input);
array_splice($input, -1);

// rimuove il primo elemento di $input
array_shift($input);
array_splice($input, 0, 1);

// inserisce un elemento all'inizio di $input
array_unshift($input, $x, $y);
array_splice($input, 0, 0, array($x, $y));

// sostituisce il valore di $input all'indice $x
$input[$x] = $y; // per gli array in cui la chiave è uguale all'offset
array_splice($input, $x, 1, $y);

?>
